package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_factorialDouble_TriageGen0Test {

    private static final double DELTA = 1e-10;



    @Test
    public void testFactorialDouble_SmallPositive() {
        // 1! = 1
        assertEquals(1.0, MathUtils.factorialDouble(1), DELTA);
        // 3! = 6
        assertEquals(6.0, MathUtils.factorialDouble(3), DELTA);
        // 5! = 120
        assertEquals(120.0, MathUtils.factorialDouble(5), DELTA);
    }






}

